
import json
from pathlib import Path

# Folder containing your extracted FPGA parameters.
PARAM_DIR = Path("fpga_params")
JSON_PATH = PARAM_DIR / "quantization_metadata.json"

# Load the metadata generated by your extraction script.
with open(JSON_PATH, "r", encoding="utf-8") as f:
    metadata = json.load(f)


def print_metadata(obj, indent=0):
    """Print nested metadata in a readable format."""
    prefix = " " * indent

    if isinstance(obj, dict):
        for key, value in obj.items():
            if isinstance(value, (dict, list)):
                print(f"{prefix}{key}:")
                print_metadata(value, indent + 4)
            else:
                print(f"{prefix}{key}: {value}")

    elif isinstance(obj, list):
        for i, value in enumerate(obj):
            print(f"{prefix}[{i}]")
            print_metadata(value, indent + 4)

    else:
        print(f"{prefix}{obj}")


print("=" * 60)
print("QUANTIZATION METADATA")
print("=" * 60)
print_metadata(metadata)
